DELIMITER $$
CREATE TRIGGER `delete_stok_barang_inventaris` AFTER DELETE ON `inventaris` FOR EACH ROW BEGIN
            DECLARE jenis_barang_id INT;
            SELECT id_jenis_barang INTO jenis_barang_id FROM barang WHERE id_barang = OLD.id_barang;
            
            IF jenis_barang_id = 3 THEN
                UPDATE barang SET stok_barang = stok_barang + OLD.jumlah_barang WHERE id_barang = OLD.id_barang;
            END IF;
        END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `store_stok_barang_inventaris` AFTER INSERT ON `inventaris` FOR EACH ROW BEGIN
            DECLARE jenis_barang_id INT;
            SELECT id_jenis_barang INTO jenis_barang_id FROM barang WHERE id_barang = NEW.id_barang;
            
            IF jenis_barang_id = 3 THEN
                UPDATE barang SET stok_barang = stok_barang - NEW.jumlah_barang WHERE id_barang = NEW.id_barang;
            END IF;
        END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_stok_barang_inventaris` AFTER UPDATE ON `inventaris` FOR EACH ROW BEGIN
        UPDATE barang 
        SET stok_barang = stok_barang + IFNULL(OLD.jumlah_barang, 0) - IFNULL(NEW.jumlah_barang, 0)         
        WHERE id_barang = NEW.id_barang;
        END
$$
DELIMITER ;

